# Re-run everything in one block
from z3 import *
import time

weeks = 6
groups = 8
size = 4
golfers = 32

start = time.time()

g = [[Int(f'g_{w}_{p}') for p in range(golfers)] for w in range(weeks)]

s = Solver()

# Domain constraints
for w in range(weeks):
    for p in range(golfers):
        s.add(g[w][p] >= 0, g[w][p] < groups)

# Each group has exactly 'size' members each week
for w in range(weeks):
    for grp in range(groups):
        s.add(Sum([If(g[w][p] == grp, 1, 0) for p in range(golfers)]) == size)

# No pair meets more than once
for p1 in range(golfers):
    for p2 in range(p1+1, golfers):
        s.add(Sum([If(g[w][p1] == g[w][p2], 1, 0) for w in range(weeks)]) <= 1)

# Symmetry breaking: fix week 0 groups
for p in range(golfers):
    s.add(g[0][p] == p // size)

# Symmetry breaking: in each week, golfer 0 is in group 0
for w in range(1, weeks):
    s.add(g[w][0] == 0)

print("Solving...")
result = s.check()
print(f"Result: {result}, Time: {time.time()-start:.1f}s")

if result == sat:
    m = s.model()
    schedule = [[m[g[w][p]].as_long() for p in range(golfers)] for w in range(weeks)]

    for w in range(weeks):
        print(f"Week {w}: {schedule[w]}")

    # Verify
    errors = 0
    for w in range(weeks):
        for grp in range(groups):
            cnt = schedule[w].count(grp)
            if cnt != size:
                print(f"ERROR: Week {w}, Group {grp} has {cnt} members")
                errors += 1

    for p1 in range(golfers):
        for p2 in range(p1+1, golfers):
            meetings = sum(1 for w in range(weeks) if schedule[w][p1] == schedule[w][p2])
            if meetings > 1:
                print(f"ERROR: Golfers {p1} and {p2} meet {meetings} times")
                errors += 1

    if errors == 0:
        print("Solution is VALID!")

    # Create flat list
    flat = []
    for w in range(weeks):
        flat.extend(schedule[w])
    print(f"\nFlat list ({len(flat)} entries):")
    print(flat)
